class Solution {
public:
    int reductionOperations(vector<int>& nums) {
        sort(nums.begin(), nums.end());
        int ans = 0, rank = 0, n = nums.size();
        for (int i = 1; i < n; ++i) {
            if (nums[i] > nums[i - 1]) rank++;
            ans += rank;
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public int reductionOperations(int[] nums) {
        Arrays.sort(nums);
        int ans = 0, rank = 0, n = nums.length;
        for (int i = 1; i < n; ++i) {
            if (nums[i] > nums[i - 1]) rank++;
            ans += rank;
        }
        return ans;
    }
}

/**
 * @param {number[]} nums
 * @return {number}
 */
var reductionOperations = function(nums) {
    nums.sort((a, b) => a - b);
    let ans = 0, rank = 0;
    for (let i = 1; i < nums.length; ++i) {
        if (nums[i] > nums[i - 1]) rank++;
        ans += rank;
    }
    return ans;
};
